const REP_KEYS = { council: ['seer', 'grok'], collegium: ['tobias', 'grok'], rem: ['seer', 'tobias'] };
const rep = (s, who) => {
  const out = [];
  for (const k of REP_KEYS[who]) {
    const v = s.choices[k];
    const line = v && REP[who][k] && REP[who][k][v];
    if (line) out.push(line);
  }
  return out;
};
const isCouncil = (s) => flag(s, 'fac_council');
const isCollegium = (s) => flag(s, 'fac_collegium');
const isRem = (s) => flag(s, 'fac_rem');
const GOLD = (n) => (s) => s.gold >= n;
const CLS = (k) => (s) => s.cls === k;

// ---------------------------------------------------------------- Фаддей
E('faddei', (s) => {
  if (active(s, 'c1')) return 'faddei_c1';
  if (active(s, 'c2') && ready(s, 'c2')) return 'faddei_c2done';
  if (active(s, 'c2')) return 'faddei_c2wait';
  if (active(s, 'c3')) return 'faddei_c3wait';
  if (active(s, 'c4') || active(s, 'c5')) return 'faddei_dig';
  if (active(s, 'c6') && flag(s, 'beacon2')) return 'faddei_c6done';
  if (active(s, 'c6')) return 'faddei_c6wait';
  if (active(s, 'c7') && !flag(s, 'faction_chosen')) return 'faddei_c7';
  if (active(s, 'c7')) return 'faddei_c7wait';
  if (done(s, 'c7')) return 'faddei_after';
  return 'faddei_idle';
});
