N('avram_expose', { t: ['Стражница хватает его под локоть. Он не сопротивляется. На тебя он не смотрит, потом смотрит один раз, коротко, как смотрят на того, кого не прощают и не проклинают.', '— Ладно. Ладно. Только пусть не бьют по рукам. Руки нужны, чтобы держать тарелку.'], c: [c('Уйти')] });
